* { box-sizing: border-box; }
:root { color-scheme: light; font-family: system-ui, sans-serif; color: #173333; background: #e8f0e9; }
body { margin: 0; min-width: 360px; min-height: 100vh; padding: 32px 16px; display: grid; place-items: center; background: radial-gradient(ellipse at 50% 0%, #f8f1d9, #e8f0e9 62%); font-size: 16px; }
.booking-card { width: min(100%, 520px); padding: 30px; border: 1px solid #d5e1d9; border-radius: 24px; background: #fffefa; box-shadow: 0 18px 55px #17333318; }
.eyebrow { margin: 0 0 8px; color: #bd694c; font-size: 16px; font-weight: 800; letter-spacing: .12em; }
h1 { margin: 0; font-size: clamp(28px, 7vw, 38px); line-height: 1.1; }
.intro { margin: 10px 0 24px; color: #526b65; }
.bus { padding: 18px 18px 14px; border: 2px solid #b6cbc0; border-radius: 56px 56px 24px 24px; background: #f1f6f0; }
.driver { height: 48px; display: flex; align-items: flex-start; justify-content: space-between; padding: 0 10px; color: #668178; font-size: 16px; font-weight: 700; }
.wheel { color: #bd694c; font-size: 24px; line-height: 1; }
.seat-map { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)) 26px repeat(2, minmax(0, 1fr)); gap: 8px 7px; }
.seat { min-height: 42px; padding: 4px 2px; border: 2px solid #5e9383; border-radius: 11px 11px 7px 7px; background: #fffefa; color: #173333; font: inherit; font-size: 16px; font-weight: 700; cursor: pointer; transition: transform .12s, background .12s, box-shadow .12s; }
.seat:nth-child(4n+1) { grid-column: 1; }
.seat:nth-child(4n+2) { grid-column: 2; }
.seat:nth-child(4n+3) { grid-column: 4; }
.seat:nth-child(4n) { grid-column: 5; }
.seat:hover:not(:disabled) { transform: translateY(-2px); background: #e0eee5; }
.seat:active:not(:disabled) { transform: scale(.96); }
.seat:focus-visible { outline: 3px solid #bd694c; outline-offset: 3px; z-index: 1; }
.seat.selected { border-color: #173f3b; background: #246b5c; color: white; box-shadow: inset 0 -4px #174c43; }
.seat.booked { border-color: #c7ceca; background: #dfe4e1; color: #6b7772; cursor: not-allowed; text-decoration: line-through; }
.legend { display: flex; flex-wrap: wrap; justify-content: center; gap: 16px; margin-top: 20px; color: #526b65; font-size: 16px; }
.legend span { display: inline-flex; align-items: center; gap: 7px; }
.key { width: 16px; height: 16px; display: inline-block; border: 2px solid #5e9383; border-radius: 5px; background: #fffefa; }
.key.selected { border-color: #246b5c; background: #246b5c; }
.key.booked { border-color: #c7ceca; background: #dfe4e1; }
.summary { display: flex; justify-content: space-between; align-items: center; gap: 16px; margin-top: 24px; padding-top: 20px; border-top: 1px solid #dce6de; }
h2 { margin: 0 0 5px; font-size: 18px; }
#chosen-seats { margin: 0; color: #526b65; overflow-wrap: anywhere; }
.price-block { text-align: right; }
.price-block span { display: block; color: #526b65; }
.price-block strong { font-size: 28px; }
.price-block strong::before { content: "¤"; margin-right: 4px; font-size: 18px; }
.price-note { margin: 10px 0 0; color: #526b65; font-size: 16px; text-align: right; }
.status { min-height: 24px; margin: 12px 0 0; color: #a44e36; font-weight: 650; }
@media (max-width: 420px) { body { padding: 16px 10px; } .booking-card { padding: 22px 16px; } .bus { padding: 16px 12px 12px; } .seat-map { grid-template-columns: repeat(2, minmax(0, 1fr)) 18px repeat(2, minmax(0, 1fr)); gap: 7px 5px; } .seat { min-height: 40px; font-size: 16px; } }

const map = document.querySelector('#seat-map');
const chosenOutput = document.querySelector('#chosen-seats');
const totalOutput = document.querySelector('#total-price');
const statusOutput = document.querySelector('#status');
const bookedSeats = new Set(['1B', '3D', '6A', '8C', '10B']);
const selectedSeats = new Set();
const columns = ['A', 'B', 'C', 'D'];

for (let row = 1; row <= 10; row += 1) {
  for (const column of columns) {
    const code = `${row}${column}`;
    const button = document.createElement('button');
    button.type = 'button';
    button.className = 'seat';
    button.textContent = code;
    button.setAttribute('aria-label', `Seat ${code}${bookedSeats.has(code) ? ', booked' : ', available'}`);
    button.setAttribute('aria-pressed', 'false');
    if (bookedSeats.has(code)) {
      button.disabled = true;
      button.classList.add('booked');
    } else {
      button.addEventListener('click', () => toggleSeat(code, button));
    }
    map.append(button);
  }
}

function toggleSeat(code, button) {
  statusOutput.textContent = '';
  if (selectedSeats.has(code)) {
    selectedSeats.delete(code);
    button.classList.remove('selected');
    button.setAttribute('aria-pressed', 'false');
  } else {
    if (selectedSeats.size === 4) {
      statusOutput.textContent = 'You can choose up to 4 seats.';
      return;
    }
    selectedSeats.add(code);
    button.classList.add('selected');
    button.setAttribute('aria-pressed', 'true');
  }
  updateSummary();
}

function updateSummary() {
  const seats = [...selectedSeats].sort((a, b) => Number(a.slice(0, -1)) - Number(b.slice(0, -1)) || a.slice(-1).localeCompare(b.slice(-1)));
  const subtotal = seats.length * 12;
  const total = seats.length === 4 ? subtotal * 0.9 : subtotal;
  chosenOutput.textContent = seats.length ? seats.join(', ') : 'None selected';
  totalOutput.textContent = Number.isInteger(total) ? String(total) : total.toFixed(2);
  document.querySelector('#price-note').textContent = seats.length === 4
    ? 'Four-seat discount applied · 10% off'
    : '12 per seat · 10% off when you choose 4';
}
